import flag_gems

from . import base

DEVICE = flag_gems.device
VENDOR = flag_gems.vendor_name

# LU-based inversion requires fp32+ precision; half-precision dtypes lack
# the dynamic range for pivoted elimination
_TEST_DTYPES = [torch.float32, torch.float64] if VENDOR == "nvidia" else [torch.float32]


class LinalgInvExBenchmark(base.Benchmark):
    DEFAULT_SHAPE_DESC = "input shape"
    DEFAULT_DTYPES = _TEST_DTYPES

    def set_shapes(self, shape_file_path=None):
        # Always use custom square matrix shapes for matrix inversion
        self.shapes = [
            (4, 4),
            (8, 8),
            (16, 16),
            (32, 32),
            (4, 16, 16),
            (16, 32, 32),
        ]

    def get_case_iter(self, cur_dtype):
        for ordinal, inp_shape in enumerate(self.shapes):
            inp_shape = tuple(inp_shape)
            yield self._case_from_plan(
                cur_dtype,
                ordinal,
                base.BenchmarkCasePlan(
                    shape={"input": list(inp_shape)},
                    builder_args=(inp_shape,),
                ),
            )

    def build_inputs(self, case):
        plan = case.builder_args[0]
        (inp_shape,) = plan.builder_args
        inp_shape = tuple(inp_shape)
        n = inp_shape[-1]
        # Generate well-conditioned invertible matrix using diagonal dominance
        # Use CPU tensor creation then move to device to avoid FlagGems
        # operator interference during input generation
        A = torch.randn(inp_shape, dtype=case.dtype, device="cpu")
        for i in range(n):
            A[..., i, i] = A[..., i, i] + n
        A = A.to(self.device)
        return A, {}


